with with_gaps as (select *, case when lag(event_time) over (partition by event_type order by event_time, id) is null or event_time > lag(event_time) over (partition by event_type order by event_time, id) + interval '90' day then 1 else 0 end as is_new_burst from web_events) select id, session_id, event_type, event_time, duration_sec, sum(is_new_burst) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as island_id from with_gaps
